import json


class Inventory:
    def __init__(self, stock):
        self.stock = dict(stock)
        self.reservations = {}

    def expire(self, now):
        for key in list(self.reservations):
            expires = self.reservations[key]["expires"]
            if expires is not None and expires <= now:
                del self.reservations[key]

    def available(self, sku, now=None):
        if now is not None:
            self.expire(now)
        return self.stock.get(sku, 0) - sum(r["qty"] for r in self.reservations.values() if r["sku"] == sku)

    def reserve(self, key, sku, qty, now=0, ttl=None):
        if qty <= 0:
            raise ValueError("qty must be positive")
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        self.expire(now)
        if key in self.reservations:
            r = self.reservations[key]
            return r["sku"] == sku and r["qty"] == qty
        if self.available(sku) < qty:
            return False
        expires = now + ttl if ttl is not None else None
        self.reservations[key] = {"sku": sku, "qty": qty, "expires": expires}
        return True

    def release(self, key):
        return self.reservations.pop(key, None) is not None

    def dumps(self):
        return json.dumps({"stock": self.stock, "reservations": self.reservations})

    @classmethod
    def loads(cls, text):
        data = json.loads(text)
        inv = cls(data["stock"])
        inv.reservations = {key: dict(r) for key, r in data["reservations"].items()}
        return inv
